    /// The next instant at which [`Tui::tick`] has work to do (pending render
    /// deadline or a terminal-side flush deadline), for event-loop timeout
    /// computation. Rust addition replacing upstream's implicit timers.
    pub fn next_deadline(&self) -> Option<Instant> {
        let render_deadline = {
            let schedule = lock_shared(&self.schedule);
            if schedule.requested {
                schedule.deadline
            } else {
                None
            }
        };
        let terminal_deadline = self.lock_inner().terminal.next_flush_deadline();
        [render_deadline, terminal_deadline]
            .into_iter()
            .flatten()
            .min()
    }

    /// Whether unprocessed input events, queued mutations or a pending render
    /// exist (event loops can use this to tick without waiting).
    pub fn has_pending_work(&self) -> bool {
        !lock_shared(&self.inbox).is_empty()
            || !lock_shared(&self.pending).is_empty()
            || lock_shared(&self.schedule).requested
    }

